{
        if( jpeg->eman.pub.num_warnings != 0 ) {
                g_warning( _( "read gave %ld warnings" ),
                        jpeg->eman.pub.num_warnings );
                g_warning( "%s", vips_error_buffer() );

                /* Make the message only appear once.
                 */
                jpeg->eman.pub.num_warnings = 0;
        }

